  app_title: "படச் சுருக்கி & அளவு மாற்றி",
  intro: "ஒரே நேரத்தில் 100 படங்களின் அளவை மாற்றி, சுருக்கி, வாட்டர்மார்க் சேர்த்து, பெயர் மாற்றலாம்: Instagram, WhatsApp ஸ்டேட்டஸ், YouTube, Amazon, Flipkart, உங்கள் இணையதளம் ஆகியவற்றுக்கு.",
  privacy_title: "உங்கள் கோப்புகள் இந்தச் சாதனத்தை விட்டு வெளியே போகாது.",
  privacy_body: "படங்கள் இந்த உலாவிக்குள்ளேயே உருவாகின்றன, எதுவும் பதிவேற்றப்படுவதில்லை. அதனால் புதிய பொருட்களின் படங்கள், வாடிக்கையாளர் வேலை, குடும்பப் படங்கள் பாதுகாப்பாக இருக்கும். GPS இருப்பிடம் போன்ற மறைந்த தகவல்கள் நீக்கப்படும்.",
  drop_title: "படங்களை இங்கே விடுங்கள்",
  drop_hint: "JPG, PNG, WebP, HEIC (iPhone), GIF, AVIF. ஒரே முறையில் 100 வரை.",
  drop_keys: "குறிப்பு: ஒரு படத்தை நகலெடுத்து இங்கே ஒட்ட <kbd>Ctrl</kbd> + <kbd>V</kbd> அழுத்துங்கள்.",
