  p_custom: "சொந்த அளவு",
  pn_ig_portrait: "ஃபீடில் அதிக இடம் பிடிக்கும். முகங்களையும் எழுத்துகளையும் ஓரங்களிலிருந்து தள்ளி வையுங்கள்.",
  pn_ig_grid: "புதிய நீளமான சுயவிவரக் கட்டத்துடன் பொருந்தும், அதனால் சுயவிவரத்தில் எதுவும் வெட்டப்படாது. விளம்பரங்களுக்கு 4:5 பயன்படுத்துங்கள்.",
  pn_ig_square: "Instagram, Facebook, WhatsApp, LinkedIn எல்லாவற்றிலும் வேலை செய்யும்.",
  pn_story: "Instagram, Facebook ஸ்டோரி, ரீல் அட்டை, WhatsApp ஸ்டேட்டஸ், YouTube Shorts ஆகியவற்றுக்கு. மங்கலான பின்னணியுடன் \"முழுப் படம்\" தேர்ந்தால் படம் முழுவதும் தெரியும். மேலே, கீழே உள்ள 250 px-இல் எழுத்துகள் வேண்டாம்.",
  pn_yt_thumb: "கீழ் வலது மூலையைக் காலியாக விடுங்கள்: அங்கே வீடியோவின் நீளம் தெரியும். பெரிய, தடித்த எழுத்துகள் சிறப்பாக வேலை செய்யும்.",
  pn_fb_cover: "போனில் பக்கங்களும் கணினியில் மேல்-கீழ் பகுதிகளும் வெட்டப்படும், அதனால் எழுத்துகளையும் முகங்களையும் நடுவில் வையுங்கள்.",
  pn_li_banner: "உங்கள் LinkedIn சுயவிவரத்தின் பின்னணி. கீழ் இடது பகுதியில் உங்கள் சுயவிவரப் படம் வரும்.",
  pn_x_header: "X-இல் கீழ் இடது பகுதியை உங்கள் சுயவிவரப் படம் மறைக்கும்.",
  pn_link: "உங்கள் இணையதள இணைப்பு WhatsApp, LinkedIn அல்லது Facebook-இல் பகிரப்படும்போது இந்தப் படம்தான் தெரியும்.",
  pn_pin: "நீளமான 2:3 பின்களுக்கு Pinterest ஃபீடில் அதிக இடம் கிடைக்கும்.",
  pn_marketplace: "முதன்மைப் பொருள் படம்: முழு வெள்ளைப் பின்னணி, பொருள் சதுரத்தின் சுமார் 85–90% நிரப்ப வேண்டும், வாட்டர்மார்க் அல்லது எழுத்து வேண்டாம். 1000 px அல்லது அதற்கு மேல் இருந்தால் வாங்குபவர்கள் பெரிதாக்கிப் பார்க்கலாம்.",
  pn_catalog: "WhatsApp Business பட்டியல், Instagram கடை அல்லது Meesho-வுக்கான தெளிவான சதுரப் படங்கள்.",
  pn_web_hero: "இணையதளத்தின் மேலே முழு அகல பேனர். பக்கம் வேகமாகத் திறக்க WebP தேர்ந்தெடுங்கள்.",
  pn_web_blog: "கட்டுரைகள், பொருள் பக்கங்களுக்குள் உள்ள படங்கள். உயரம் படத்துக்கு ஏற்ப தானாக அமையும்.",
  pn_email: "மின்னஞ்சல் செய்தி மடல்கள் சுமார் 600 px அகலம். உயரம் படத்துக்கு ஏற்ப அமையும்.",
  pn_wa_share: "WhatsApp எப்படியும் படங்களை சுமார் 1600 px-க்குச் சுருக்கும். இந்த அளவில் படங்கள் தெளிவாக, இலேசாக, வேகமாக அனுப்பக்கூடியதாக இருக்கும். எதுவும் வெட்டப்படாது.",
  pn_original: "அகலமும் உயரமும் அப்படியே இருக்கும், கோப்பு மட்டும் சிறியதாகும்.",
  pn_custom: "பிக்சலில் உங்கள் அகலத்தையும் உயரத்தையும் எழுதுங்கள்.",
  limit_note: "கோப்புகள் தானாகவே {kb} KB-க்குள் வைக்கப்படும்.",
