  mode_exact: "நீட்டு",
  mode_fit_hint: "படம் முழுவதும் இருக்கும். காலி இடம் ஒரு நிறத்தால் அல்லது படத்தின் மங்கலான நகலால் நிரப்பப்படும்.",
  mode_fill_hint: "படம் சட்டகம் முழுவதையும் நிரப்பும், கூடுதல் பகுதி வெட்டப்படும். முன்னோட்டத்தில் சட்டகத்தை நகர்த்தி எந்தப் பகுதி இருக்க வேண்டும் எனத் தேர்ந்தெடுங்கள்.",
  mode_exact_hint: "படம் சரியான அளவுக்குள் அழுத்தப்படும். முகங்களும் பொருட்களும் நீட்டப்பட்டது போலத் தெரியலாம்.",
