  fmt_webp: "அதே தோற்றத்தில் JPG-ஐ விட சுமார் 25–35% சிறியது. இணையதளங்களுக்கு அருமை. சில பழைய செயலிகள் ஏற்காது.",
  fmt_png: "ஒவ்வொரு பிக்சலையும் ஒளிபுகும் பின்னணியையும் காக்கும். லோகோ, திரைப்பிடிப்பு, எழுத்துள்ள கிராஃபிக்ஸுக்குச் சிறந்தது. கோப்பு பெரியதாக இருக்கும்.",
