  pn_story: "Instagram, Facebook స్టోరీలు, రీల్ కవర్లు, WhatsApp స్టేటస్, YouTube Shorts కోసం. మసక బ్యాక్‌గ్రౌండ్‌తో \"పూర్తి ఫోటో\" ఎంచుకుంటే ఫోటో మొత్తం కనిపిస్తుంది. పైన, కింద 250 px లో అక్షరాలు పెట్టకండి.",
  pn_yt_thumb: "కింది కుడి మూలను ఖాళీగా ఉంచండి: అక్కడ వీడియో నిడివి కనిపిస్తుంది. పెద్ద, బోల్డ్ అక్షరాలు బాగా పనిచేస్తాయి.",
  pn_fb_cover: "ఫోన్‌లో పక్కలు, కంప్యూటర్‌లో పై-కింది భాగాలు కత్తిరించబడతాయి, కాబట్టి అక్షరాలు, ముఖాలు మధ్యలో ఉంచండి.",
  pn_li_banner: "మీ LinkedIn ప్రొఫైల్ బ్యాక్‌గ్రౌండ్. కింది ఎడమ భాగంలో మీ ప్రొఫైల్ ఫోటో వస్తుంది.",
  pn_x_header: "X లో కింది ఎడమ భాగాన్ని మీ ప్రొఫైల్ ఫోటో కప్పేస్తుంది.",
  pn_link: "మీ వెబ్‌సైట్ లింక్ WhatsApp, LinkedIn లేదా Facebook లో షేర్ అయినప్పుడు ఈ ఫోటోనే కనిపిస్తుంది.",
  pn_pin: "పొడవైన 2:3 పిన్‌లకు Pinterest ఫీడ్‌లో ఎక్కువ స్థలం దొరుకుతుంది.",
  pn_marketplace: "ప్రధాన ప్రొడక్ట్ ఫోటో: పూర్తి తెలుపు బ్యాక్‌గ్రౌండ్, ప్రొడక్ట్ చతురస్రంలో దాదాపు 85–90% నిండాలి, వాటర్‌మార్క్ లేదా అక్షరాలు వద్దు. 1000 px లేదా అంతకంటే ఎక్కువ ఉంటే కొనుగోలుదారులు జూమ్ చేయగలరు.",
  pn_catalog: "WhatsApp Business కేటలాగ్, Instagram షాప్ లేదా Meesho కోసం స్పష్టమైన చతురస్ర ఫోటోలు.",
  pn_web_hero: "వెబ్‌సైట్ పైభాగంలో పూర్తి వెడల్పు బ్యానర్. పేజీ త్వరగా తెరుచుకోవడానికి WebP ఎంచుకోండి.",
  pn_web_blog: "వ్యాసాలు, ప్రొడక్ట్ పేజీల లోపలి ఫోటోలు. ఎత్తు ఫోటోను బట్టి దానంతటదే నిర్ణయమవుతుంది.",
  pn_email: "ఈమెయిల్ న్యూస్‌లెటర్లు దాదాపు 600 px వెడల్పు ఉంటాయి. ఎత్తు ఫోటోను బట్టి నిర్ణయమవుతుంది.",
  pn_wa_share: "WhatsApp ఎలాగూ ఫోటోలను దాదాపు 1600 px కి తగ్గిస్తుంది. ఈ సైజ్‌లో ఫోటోలు స్పష్టంగా, తేలికగా, త్వరగా పంపేలా ఉంటాయి. ఏదీ కత్తిరించబడదు.",
  pn_original: "వెడల్పు, ఎత్తు అలాగే ఉంటాయి, ఫైల్ మాత్రమే తేలికవుతుంది.",
