  pn_wa_share: "WhatsApp ಹೇಗಿದ್ದರೂ ಫೋಟೋಗಳನ್ನು ಸುಮಾರು 1600 px ಗೆ ಚಿಕ್ಕದಾಗಿಸುತ್ತದೆ. ಈ ಗಾತ್ರದಲ್ಲಿ ಫೋಟೋಗಳು ಸ್ಪಷ್ಟ, ಹಗುರ ಮತ್ತು ಬೇಗ ಕಳುಹಿಸುವಂತಿರುತ್ತವೆ. ಏನೂ ಕತ್ತರಿಸುವುದಿಲ್ಲ.",
  pn_original: "ಅಗಲ ಮತ್ತು ಎತ್ತರ ಹಾಗೆಯೇ ಇರುತ್ತದೆ, ಫೈಲ್ ಮಾತ್ರ ಹಗುರವಾಗುತ್ತದೆ.",
  pn_custom: "ಪಿಕ್ಸೆಲ್‌ಗಳಲ್ಲಿ ನಿಮ್ಮ ಅಗಲ ಮತ್ತು ಎತ್ತರ ಬರೆಯಿರಿ.",
