  empty: "ಇನ್ನೂ ಫೋಟೋಗಳಿಲ್ಲ. ಫೋಟೋಗಳನ್ನು ಆಯ್ಕೆಮಾಡಿ, ಇಲ್ಲಿ ಬಿಡಿ ಅಥವಾ ಮಾದರಿ ಫೋಟೋಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿ.",
  help_title: "ಹೇಗೆ ಬಳಸುವುದು · ಕೆಲಸಕ್ಕೆ ಐಡಿಯಾಗಳು",
  tip1: "ಬಟನ್‌ನಿಂದ, ಫೋಟೋಗಳನ್ನು ಪುಟದ ಮೇಲೆ ಎಳೆದು ಅಥವಾ ಪೇಸ್ಟ್ ಮಾಡಿ (Ctrl + V) ಫೋಟೋಗಳನ್ನು ಸೇರಿಸಿ. ಒಮ್ಮೆಗೆ 100 ರವರೆಗೆ, ಫೋನ್‌ನಲ್ಲೂ.",
