  pn_wa_share: "WhatsApp എന്തായാലും ഫോട്ടോകൾ ഏകദേശം 1600 px ആയി ചെറുതാക്കും. ഈ വലുപ്പത്തിൽ ഫോട്ടോകൾ വ്യക്തവും ഭാരം കുറഞ്ഞതും വേഗം അയയ്ക്കാവുന്നതുമായിരിക്കും. ഒന്നും മുറിയില്ല.",
  pn_original: "വീതിയും ഉയരവും അതുപോലെ നിൽക്കും, ഫയൽ മാത്രം ചെറുതാകും.",
  pn_custom: "പിക്സലിൽ നിങ്ങളുടെ വീതിയും ഉയരവും എഴുതുക.",
