  mode_fill_hint: "ഫോട്ടോ ഫ്രെയിം മുഴുവൻ നിറയ്ക്കും, അധിക ഭാഗം മുറിഞ്ഞുപോകും. പ്രിവ്യൂവിൽ ഫ്രെയിം നീക്കി ഏത് ഭാഗം നിൽക്കണമെന്ന് തിരഞ്ഞെടുക്കുക.",
