  tip2: "വലുപ്പം തിരഞ്ഞെടുക്കുക. \"നിറയ്ക്കുക\" ഫോട്ടോ കൃത്യമായ ആകൃതിയിൽ മുറിക്കും: ഫോട്ടോ തുറന്ന് പ്രധാന ഭാഗം നിലനിർത്താൻ ഫ്രെയിം നീക്കുക. \"മുഴുവൻ ഫോട്ടോ\" എല്ലാം നിലനിർത്തി അരിക് ചേർക്കും; WhatsApp സ്റ്റാറ്റസിന് മങ്ങിയ പശ്ചാത്തലം വളരെ ഭംഗിയാണ്.",
