  tip6: "ആശയം: ഒരു സോഷ്യൽ മീഡിയ മാനേജർ Instagram പോസ്റ്റുകൾക്കുള്ള ഫോട്ടോകൾ ഉണ്ടാക്കി, പിന്നെ \"സ്റ്റോറി\" അമർത്തി അതേ ഫോട്ടോകൾ നിമിഷങ്ങൾക്കുള്ളിൽ 9:16-ൽ നേടുന്നു. ഫയലുകൾ ക്രമത്തിലിരിക്കാൻ പേരിന്റെ മാതൃക {name}_story ആക്കുക.",
