  inside1: "നിങ്ങളുടെ ബ്രൗസർ ഓരോ ഫോട്ടോയും തുറന്ന് പുതിയ വലുപ്പത്തിൽ ക്യാൻവാസിൽ വീണ്ടും വരയ്ക്കുന്നു. ഒന്നും ഒരു സർവറിലേക്കും പോകുന്നില്ല. ഈ പേജ് ഒരിക്കൽ തുറന്നാൽ ഇന്റർനെറ്റ് ഇല്ലാത്തപ്പോഴും പ്രവർത്തിക്കും.",
  inside2: "കണ്ണിന് കഷ്ടിച്ച് കാണാവുന്ന സൂക്ഷ്മ വിശദാംശങ്ങൾ നീക്കിയാണ് JPG, WebP എന്നിവ ഫയൽ ചെറുതാക്കുന്നത്. കുറഞ്ഞ ഗുണനിലവാരം എന്നാൽ ചെറിയ ഫയൽ, പക്ഷേ കൂടുതൽ മങ്ങലും ചതുരപ്പാടുകളും. PNG ഓരോ പിക്സലും സൂക്ഷിക്കും, അതിനാൽ വലുതാണ്.",
  inside3: "ഫോൺ ഫോട്ടോകളിൽ മറഞ്ഞിരിക്കുന്ന വിവരങ്ങൾ (EXIF) ഉണ്ട്: ഫോൺ മോഡൽ, തീയതി, പലപ്പോഴും നിങ്ങളുടെ വീടിന്റെയോ കടയുടെയോ കൃത്യമായ GPS ലൊക്കേഷൻ. ഫോട്ടോ വീണ്ടും വരയ്ക്കുമ്പോൾ ഇവയെല്ലാം നീങ്ങും, അതിനാൽ പോസ്റ്റ് ചെയ്യുന്നത് സുരക്ഷിതമാണ്.",
  inside4: "\"ഫയൽ വലുപ്പം അനുസരിച്ച്\" പല ഗുണനിലവാരങ്ങൾ പരീക്ഷിക്കുന്നു, ഓരോ തവണയും വ്യത്യാസം പകുതിയാക്കുന്നു, ഒരു നമ്പർ ഊഹിക്കുന്ന കളി പോലെ, ഫയൽ നിങ്ങളുടെ പരിധിക്കുള്ളിൽ വരുന്നതുവരെ."
